  ($str$variable$str$, 'USA', $str$2026-AssyPlastic$str$, $str$defaultMoldBaseConfiguration$str$, $str$reference export baseline$str$, NULL, $str$Defines the mold base configuration for rotary platens. Available options are Let ePriori Decide, Separate, Combined or Rotating Stack. Separate implies that each stage is injected into individual mold blanks. Combined implies that each stage is injected into the same mold blank. Rotating Stack implies that back to back mold bases rotate about a vertical axis.$str$, $jsonb${"Variable Name":"defaultMoldBaseConfiguration","String Value":"reference export baseline","Unit Type Name":null,"Notes":"Defines the mold base configuration for rotary platens. Available options are Let ePriori Decide, Separate, Combined or Rotating Stack. Separate implies that each stage is injected into individual mold blanks. Combined implies that each stage is injected into the same mold blank. Rotating Stack implies that back to back mold bases rotate about a vertical axis.","Category":"General"}$jsonb$::jsonb),
  ($str$variable$str$, 'USA', $str$2026-AssyPlastic$str$, $str$defaultMoldPlating$str$, $str$None$str$, NULL, $str$Default mold plating. Available options are in listed in tblToolCoating$str$, $jsonb${"Variable Name":"defaultMoldPlating","String Value":"None","Unit Type Name":null,"Notes":"Default mold plating. Available options are in listed in tblToolCoating","Category":"General"}$jsonb$::jsonb),
  ($str$variable$str$, 'USA', $str$2026-AssyPlastic$str$, $str$defaultMoldTemperatureIncrease$str$, $str$0$str$, $str$Temperature$str$, $str$This value is added on to the mold temperature variable that is used in the cooling time equation. It allows for local differences in mold temperatures that can occur in the event of limited access for cooling channels.$str$, $jsonb${"Variable Name":"defaultMoldTemperatureIncrease","String Value":0,"Unit Type Name":"Temperature","Notes":"This value is added on to the mold temperature variable that is used in the cooling time equation. It allows for local differences in mold temperatures that can occur in the event of limited access for cooling channels.","Category":"General"}$jsonb$::jsonb),
