  ($str$variable$str$, 'USA', $str$2026-AssyPlastic$str$, $str$defaultNumberOfPlates$str$, $str$2$str$, NULL, $str$Default setting for number of plates in the mold. Select from '2' for 2-Plate Molding, sprues and runners attached to part, or '3' for 3-Plate Molding where a stripper plate separates the sprues and runners from the part upon mold opening.$str$, $jsonb${"Variable Name":"defaultNumberOfPlates","String Value":2,"Unit Type Name":null,"Notes":"Default setting for number of plates in the mold. Select from '2' for 2-Plate Molding, sprues and runners attached to part, or '3' for 3-Plate Molding where a stripper plate separates the sprues and runners from the part upon mold opening.","Category":"General"}$jsonb$::jsonb),
